package com.ias.ticket;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CompletionTimingTest {
 final Instant start=Instant.parse("2026-01-01T00:00:00Z");
 Instant at(long hours){return start.plusSeconds(hours*3600);}
 @Test void prdFirstSubmissionTimelyFinalFiveHoursLateAndFrozen(){var intervals=List.of(new CompletionTiming.Interval(at(3),at(77)));var result=CompletionTiming.calculate(start,at(77),intervals,false);assertEquals(3*3600000L,result.firstMs());assertEquals(74*3600000L,result.waitMs());assertEquals(72*3600000L,result.excludedMs());assertEquals(5*3600000L,result.effectiveMs());assertEquals(result,CompletionTiming.calculate(start,at(77),intervals,false));}
 @Test void twoReturnsShareOneBudgetAndDoNotResetProcessingTime(){var intervals=List.of(new CompletionTiming.Interval(at(2),at(32)),new CompletionTiming.Interval(at(34),at(64)),new CompletionTiming.Interval(at(66),at(86)));var r=CompletionTiming.calculate(start,at(86),intervals,false);assertEquals(80*3600000L,r.waitMs());assertEquals(72*3600000L,r.excludedMs());assertEquals(14*3600000L,r.effectiveMs());}
 @Test void exactLimitRemindsButDoesNotBecomeOverLimit(){var r=CompletionTiming.calculate(start,at(75),List.of(new CompletionTiming.Interval(at(3),null)),true);assertEquals(72*3600000L,r.excludedMs());assertTrue(r.needsCoordination());assertFalse(r.currentOver72());assertEquals(3*3600000L,r.effectiveMs());}
 @Test void afterLimitTimeContinuesWithoutAutomaticDecision(){var r=CompletionTiming.calculate(start,at(76),List.of(new CompletionTiming.Interval(at(3),null)),true);assertEquals(4*3600000L,r.effectiveMs());assertTrue(r.currentOver72());assertTrue(r.needsCoordination());}
 @Test void returnBelowLimitResumesSameRoundElapsed(){var r=CompletionTiming.calculate(start,at(10),List.of(new CompletionTiming.Interval(at(3),at(8))),false);assertEquals(5*3600000L,r.excludedMs());assertEquals(5*3600000L,r.effectiveMs());assertFalse(r.needsCoordination());}
 @Test void beforeAnySolutionElapsedIsRealAndNotNegative(){var r=CompletionTiming.calculate(start,at(2),List.of(),false);assertNull(r.firstMs());assertEquals(2*3600000L,r.effectiveMs());assertEquals(0,r.excludedMs());}
 @Test void rejectOverlappingOrUnclosedPriorIntervals(){assertThrows(IllegalStateException.class,()->CompletionTiming.calculate(start,at(10),List.of(new CompletionTiming.Interval(at(2),at(6)),new CompletionTiming.Interval(at(5),at(9))),false));assertThrows(IllegalStateException.class,()->CompletionTiming.calculate(start,at(10),List.of(new CompletionTiming.Interval(at(2),null),new CompletionTiming.Interval(at(5),null)),true));}
 @Test void unsupportedReferencesOrEnabledOrUnknownConfigurationFailClosed(){var ordinary=new HashMap<String,Object>();ordinary.put("completion_scope","ORDINARY_REPAIR_V1");assertTrue(Completion.supported(ordinary,"DISABLED"));assertFalse(Completion.supported(ordinary,"ENABLED"));assertFalse(Completion.supported(ordinary,"unknown"));ordinary.put("related_business_json","{}");assertFalse(Completion.supported(ordinary,"DISABLED"));ordinary.remove("related_business_json");ordinary.put("completion_scope","OTHER");assertFalse(Completion.supported(ordinary,"DISABLED"));}
 @Test void decisionFieldsDoNotAllowConfirmReasonOrClientAuthority(){var controller=new Completion(null,null);var data=new HashMap<String,Object>(Map.of("expectedVersion","1","roundId",UUID.randomUUID().toString(),"decision","CONFIRM"));assertNotNull(controller.fields("customer-decision",data));data.put("reason","不该覆盖的理由");assertThrows(RuntimeException.class,()->controller.fields("customer-decision",data));data.remove("reason");data.put("decision",null);var invalid=assertThrows(com.ias.trust.Problem.class,()->controller.fields("customer-decision",data));assertEquals(400,invalid.status);data.put("decision","CONFIRM");data.put("verified",true);assertThrows(RuntimeException.class,()->controller.fields("customer-decision",data));}
}
